mapper.update:
UPDATE column_info
table_name = #{tableName}, column_name = #{columnName}, column_description = #{columnDescription}, is_visible = #{isVisible}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
physical_column_description = #{physicalColumnDescription}, type_name = #{typeName}, primary_key = #{primaryKey}, physical_status = #{physicalStatus}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
SET physical_status = 0,
    update_time = #{now}
WHERE datasource_id = #{datasourceId}
  AND id IN

    #{id}

  AND (physical_status IS NULL OR physical_status <> 0)

